/**
 * NORMALIZA EVENTO WHATSAPP (EVOLUTION API)
 * - Detecta automaticamente remoteJid ou remoteJidAlt
 * - Prioriza JID com @s.whatsapp.net
 * - Normaliza e gera UMA única saída: telefonelead
 */

const input = $input.first().json;
const body = input.body || {};
const data = body.data || {};
const key  = data.key || {};

// instância
const instance_id = body.instance ?? null;

// possíveis entradas de JID
const jidCandidates = [
  key.remoteJid,
  key.remoteJidAlt,
  key.participant
].filter(v => typeof v === 'string');

// função de prioridade
function pickBestJid(candidates) {
  // 1️⃣ prioridade absoluta: @s.whatsapp.net
  const primary = candidates.find(jid =>
    jid.includes('@s.whatsapp.net')
  );
  if (primary) return primary;

  // 2️⃣ fallback: qualquer JID válido que não seja status
  return candidates.find(jid =>
    !jid.startsWith('status')
  ) || null;
}

const selectedJid = pickBestJid(jidCandidates);

// normalização final
let telefonelead = null;

if (selectedJid) {
  telefonelead = selectedJid
    .replace('@s.whatsapp.net', '')
    .replace('@c.us', '')
    .replace('@lid', '')
    .trim();
}

// segurança
if (!telefonelead) {
  return [];
}

// mensagem
const message =
  data?.message?.conversation ||
  data?.message?.extendedTextMessage?.text ||
  null;

// detectar mídia
let media = null;
let media_type = null;
let media_base64 = null;
let media_mime = null;
let media_name = null;

if (data?.message?.imageMessage) {
  media = data.message.imageMessage;
  media_type = 'image';
} else if (data?.message?.audioMessage) {
  media = data.message.audioMessage;
  media_type = 'audio';
} else if (data?.message?.documentMessage) {
  media = data.message.documentMessage;
  media_type = 'document';
}

if (media) {
  media_base64 = media.base64 || null;
  media_mime = media.mimetype || null;
  media_name = media.fileName || null;
}

return [
  {
    json: {
      instance_id,
      telefonelead,
      message_id: key.id || null,
      from_me: key.fromMe === true,
      message_type: media_type || 'text',
      message,
      media_base64,
      media_mime,
      media_name,
      raw_payload: body
    }
  }
];

const body = $json.body ?? $json;
const data = body?.data;

let output = null;

// Timestamp compatível com timestamptz do Supabase
const now = new Date()
  .toISOString()
  .replace('T', ' ')
  .replace(/\.\d{3}Z$/, '');

// Resolve o ID da mensagem de forma robusta
const messageId =
  data?.messageId ||
  data?.keyId ||
  data?.key?.id ||
  null;

if (data?.status && messageId) {

  switch (data.status) {

    case 'SERVER_ACK':
    case 'SENT':
      output = {
        message_id: messageId,
        wa_sent_at: now
      };
      break;

    case 'DELIVERY_ACK':
    case 'DELIVERED':
      output = {
        message_id: messageId,
        wa_delivered_at: now
      };
      break;

    case 'READ_ACK':
    case 'READ':
      output = {
        message_id: messageId,
        wa_read_at: now
      };
      break;
  }
}

return [
  {
    json: output ?? { ignore: true }
  }
];

