const upload = $input.first().json;

// upload.Key já vem como: whatsapp-media/448697/553193044907/arquivo.ogg
const media_url = upload?.Key
  ? `${$env.SUPABASE_URL}/storage/v1/object/public/${upload.Key}`
  : null;

return [
  {
