const raw = $input.first().json;

// tenta localizar base64 em possíveis caminhos
let base64 =
  raw?.base64 ??
  raw?.data?.base64 ??
  raw?.media?.base64 ??
  null;

// se não houver base64, apenas ignora (não é mídia)
if (typeof base64 !== 'string') {
  return [];
}

// remove prefixo data:mime;base64,
if (base64.includes(',')) {
  base64 = base64.split(',')[1];
}

// valida header OGG apenas se existir
if (!base64.startsWith('T2dn')) {
  throw new Error('Base64 inválido: header OGG não encontrado');
}

return [
  {
    json: { base64 }
  }
];

