// Pegamos os dados que vieram do nó da Evolution API (ajuste o nome do nó se precisar)
const mediaData = $input.item.json;

// Se não houver base64, apenas ignoramos
if (!mediaData || !mediaData.base64) {
  return $input.item;
}

// Pegamos o Base64 puro gerado pela Evolution
let pureBase64 = mediaData.base64;

// Lógica de segurança para limpar cabeçalhos (caso existam)
if (pureBase64.includes(';base64,')) {
    pureBase64 = pureBase64.split(';base64,').pop();
}

// Criamos o binário manualmente com a assinatura OBRIGATÓRIA do Word
$input.item.binary = $input.item.binary || {};
$input.item.binary.file = { // <--- Criando a propriedade "file" que seu HTTP Request usa
    data: pureBase64,
    mimeType: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    fileName: 'documento.docx',
    fileExtension: 'docx'
};

return $input.item;

